        }
    } else {
        item.awin = isDot((((item.paOdds! - item.aodds) - item.abreak / 100 * item.paOdds!) / item.paOdds!) * 10000)
    }
}

const boddsList = (num: number, obj: OddsItem, item: OddsItem): void => {
    if (num === 2) {
        if (item.bbreak === 0) {
            item.bodds = item.pbOdds || 0
        } else {
            rebbackList(obj, item)
        }
    } else {
        item.bwin = isDot((((item.pbOdds! - item.bodds) - item.bbreak / 100 * item.pbOdds!) / item.pbOdds!) * 10000)
    }
}

const coddsList = (num: number, obj: OddsItem, item: OddsItem): void => {
    if (num === 2) {
        if (item.cbreak === 0) {
            item.codds = item.pcOdds || 0
        } else {
            recbackList(obj, item)
        }
    } else {
        item.cwin = isDot((((item.pcOdds! - item.codds) - item.cbreak / 100 * item.pcOdds!) / item.pcOdds!) * 10000)
    }
}

const doddsList = (num: number, obj: OddsItem, item: OddsItem): void => {
    if (num === 2) {
        if (item.dbreak === 0) {
            item.dodds = item.pdOdds || 0
        } else {
            redbackList(obj, item)
        }
    } else {
        item.dwin = isDot((((item.pdOdds! - item.dodds) - item.dbreak / 100 * item.pdOdds!) / item.pdOdds!) * 10000)
    }
}

const getLotteryTypeList = async () => {
    try {
        const res = await userStore.getQueryOrg(userId);
        userInfo.value = res.data;
        if(res.data.handicapList.length > 0){
            for (let j = 0; j < res.data.handicapList.length; j++) {
                if (res.data.handicapList[j] == 1) {
                    isA.value = true;
                }
                if (res.data.handicapList[j] == 2) {
                    isB.value = true;
                }
                if (res.data.handicapList[j] == 3) {
                    isC.value = true;
                }
                if (res.data.handicapList[j] == 4) {
                    isD.value = true;
                }
            }
        };
        if(res.data.lotteryList.length > 0){
            shawList.value = res.data.lotteryList;
            value1.value = res.data.lotteryList[0].lotteryId;
            lotteryName.value = res.data.lotteryList[0].lotteryName;
        }
        await getLoadOdds();
    } catch (error) {
        console.log('getLotteryTypeList error:', error);
    }
}

const getLoadOdds = async () => {
    try {
        classList.value = [];
        const res = await userStore.getMkodds(userId, value1.value);
        if(res.code == 200){
             res.data.forEach(items => {
                items.oneOdds.awin = isDot((((items.oneOdds.paOdds - items.oneOdds.aodds) - items.oneOdds.abreak / 100 * items.oneOdds.paOdds) / items.oneOdds.paOdds) * 10000)
                items.oneOdds.bwin = isDot((((items.oneOdds.pbOdds - items.oneOdds.bodds) - items.oneOdds.bbreak / 100 * items.oneOdds.pbOdds) / items.oneOdds.pbOdds) * 10000)
                items.oneOdds.cwin = isDot((((items.oneOdds.pcOdds - items.oneOdds.codds) - items.oneOdds.cbreak / 100 * items.oneOdds.pcOdds) / items.oneOdds.pcOdds) * 10000)
                items.oneOdds.dwin = isDot((((items.oneOdds.pdOdds - items.oneOdds.dodds) - items.oneOdds.dbreak / 100 * items.oneOdds.pdOdds) / items.oneOdds.pdOdds) * 10000)
                items.oddsList.forEach(item => {
                    if (item.paOdds) {
                        item.awin = isDot((((item.paOdds - item.aodds) - item.abreak / 100 * item.paOdds) / item.paOdds) * 10000)
                    }
                    if (item.pbOdds) {
                        item.bwin = isDot((((item.pbOdds - item.bodds) - item.bbreak / 100 * item.pbOdds) / item.pbOdds) * 10000)
                    }
                    if (item.pcOdds) {
                        item.cwin = isDot((((item.pcOdds - item.codds) - item.cbreak / 100 * item.pcOdds) / item.pcOdds) * 10000)
                    }
                    if (item.pdOdds) {
                        item.dwin = isDot((((item.pdOdds - item.dodds) - item.dbreak / 100 * item.pdOdds) / item.pdOdds) * 10000)
                    }
                })
            })
        }
        // 强制更新视图
        classList.value = res.data;
    } catch (error) {
        console.error('getLoadOdds error:', error);
        Toast('加载赔率数据失败');
    }
}

const isDot = (num) => {
    let result = num ? (num.toString()).indexOf(".") : 0;
    if(result != -1) {
        return num.toFixed(2);
    } else {
        return num;
    }
}

const check_count = (e) => {
    let obj = e.target
    if (obj.value != '' && obj.value.substr(0, 1) == '.') {
        obj.value = "";
    }
    obj.value = obj.value.replace(/^0*(0\.|[1-9])/, '$1');
    obj.value = obj.value.replace(/^(\-)*(\d+)\.(\d\d\d\d).*$/, '$1$2.$3');
    if (obj.value.indexOf(".") < 0 && obj.value != "") {
        if (obj.value.substr(0, 1) == '0' && obj.value.length == 2) {
            obj.value = obj.value.substr(1, obj.value.length);
        }
    }
}

const saveWater = async () => {
    loading.value = true;
    try {
        let str = false
        let str1 = false
        let t = false
        let t1 = false
        classList.value.forEach(list => {
            if (list.oddsList.length > 0) {
                list.oddsList.forEach(item => {
                    if (item.aodds > (item.paOdds || 0) || item.bodds > (item.pbOdds || 0) || 
                        item.codds > (item.pcOdds || 0) || item.dodds > (item.pdOdds || 0)) {
                        str = true
                    }
                    if (item.awin < 0 || item.bwin < 0 || item.cwin < 0 || item.dwin < 0) {
                        str1 = true
                    }
                    if (item.aodds >= 0 && item.abreak >= 0 && item.bodds >= 0 && item.bbreak >= 0 && 
                        item.codds >= 0 && item.cbreak >= 0 && item.dodds >= 0 && item.dbreak >= 0 && 
                        item.minBet >= 0 && item.maxBet >= 0 && item.maxPeriod >= 0) {
                        // 数据正常
                    } else {
                        t = true
                    }
                })
            } else {
                t1 = true
            }
        })

        if (str) {
            showToast("当前有赔率超过上级")
            return
        }
        if (str1) {
            showToast("当前利润为负数,请修改利润为正数！")
            return
        }
        if (t || t1) {
            showToast('保存数据有空值,请检查!')
            return
        }

        const params = {
            vos: classList.value,
            password:md5(formlogin.value.secound.toLowerCase()), // 这里需要根据实际情况添加加密逻辑
            type: radio.value
        }
        const res = await userStore.oddssave(params)
        showLogin.value = false;
        await getLoadOdds();
        showToast('保存成功')
        loading.value = true;
    } catch (error) {
        loading.value = false;
        showToast('保存失败');
    } finally {
        loading.value = false;
    }
}

// 生命周期
onMounted(() => {
    getLotteryTypeList();
})
